  async Task BackgroundQueryChecks(){
   int beats=0,workerThread=0;var heartbeat=new System.Windows.Threading.DispatcherTimer{Interval=TimeSpan.FromMilliseconds(25)};heartbeat.Tick+=(s,e)=>beats++;heartbeat.Start();
   var query=new BackgroundQuery<int>();var release=new System.Threading.ManualResetEventSlim(false);int uiThread=System.Threading.Thread.CurrentThread.ManagedThreadId;
   try{
    var pending=query.TryRun(()=>{workerThread=System.Threading.Thread.CurrentThread.ManagedThreadId;release.Wait();return Task.FromResult(42);});
    for(int i=0;i<100;i++)Check(query.TryRun(()=>Task.FromResult(0))==null,"Blocked audio query queued duplicate work");
    await Task.Delay(1200);Check(beats>=5&&workerThread!=uiThread,"Background audio query blocked the UI dispatcher");
    release.Set();Check(await pending==42,"Background result lost");
    var next=query.TryRun(()=>Task.FromResult(9));Check(next!=null&&await next==9,"Query gate did not reopen");
   }finally{release.Set();heartbeat.Stop();}
  }
  async Task RouteStatusContentionChecks(){
   var engine=routes.Engine;
   var sync=typeof(GraphRuntime).GetField("applyGate",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(engine);
   using(var entered=new System.Threading.ManualResetEventSlim())using(var release=new System.Threading.ManualResetEventSlim()){
    var worker=Task.Run(()=>{lock(sync){entered.Set();release.Wait(3000);}});
    try{await Task.Run(()=>entered.Wait());var watch=System.Diagnostics.Stopwatch.StartNew();int pending=engine.PendingAppRestores;Check(watch.ElapsedMilliseconds<200,"Route status waited for a pending connection");await Task.Delay(50);Check(!worker.IsCompleted,"Contention regression was not exercised");}
    finally{release.Set();}await worker;
   }
  }
